package weave

import (
	"encoding/json"
	"strings"
)

func render(b Bundle, d *Difference) []byte {
	payload, _ := json.Marshal(struct {
		Bundle Bundle      `json:"bundle"`
		Diff   *Difference `json:"diff"`
	}{b, d})
	return []byte(strings.Replace(page, "/*PAYLOAD*/", string(payload), 1))
}

const page = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Weave · Context reviewer</title><style>
:root{color-scheme:light dark;--bg:#f5f4ef;--panel:#fffefa;--ink:#212d2a;--muted:#5c6b64;--line:#d6ddd3;--accent:#20634e;--soft:#e7eee6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,sans-serif}body.dark{--bg:#121b19;--panel:#1b2824;--ink:#e4ece6;--muted:#b2c3ba;--line:#3d5047;--accent:#a0ddbf;--soft:#283d32}header{padding:28px max(22px,4vw);border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:20px}.brand{font-size:25px;font-weight:750;letter-spacing:-1px}.brand span{color:var(--accent)}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:2px;color:var(--muted)}button{font:inherit;cursor:pointer;color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:9px 15px}button:hover,button[aria-selected=true]{background:var(--soft);border-color:var(--accent)}.layout{max-width:1480px;margin:auto;display:grid;grid-template-columns:280px minmax(0,1fr);gap:36px;padding:32px 4vw}aside{min-width:0}main{min-width:0}h1{font-size:clamp(27px,4vw,43px);line-height:1.15;letter-spacing:-1px;margin:12px 0 20px}h2{font-size:23px;line-height:1.3}h3{font-size:17px}p{margin:10px 0}.muted{color:var(--muted)}.digest{overflow-wrap:anywhere;font:12px/1.6 ui-monospace,monospace}.card{padding:20px;background:var(--panel);border:1px solid var(--line);border-radius:12px;margin:16px 0}.sources button{display:block;width:100%;text-align:left;margin:8px 0;padding:11px;overflow-wrap:anywhere;font-size:13px}.sources small{display:block;color:var(--muted)}nav{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.8 ui-monospace,SFMono-Regular,monospace;margin:0;tab-size:2}#context{font-size:14px}a{color:var(--accent)}.pill{font-size:12px;color:var(--accent);background:var(--soft);border-radius:20px;padding:4px 10px}.diff-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}.diff-grid>div{min-width:0;border-left:3px solid var(--line);padding-left:14px}[hidden]{display:none!important}footer{font-size:12px;color:var(--muted);border-top:1px solid var(--line);margin-top:32px;padding-top:16px}@media(max-width:760px){.layout{display:flex;flex-direction:column;padding:22px;gap:12px}header{padding:20px}.sources{max-height:210px;overflow:auto}.diff-grid{grid-template-columns:1fr}aside .card{margin-top:0}h1{margin-top:0}}
</style></head><body><header><div><div class="brand"><span>⌘</span> Weave</div><div class="eyebrow">Context, made explicit</div></div><button id="theme" aria-label="Toggle dark mode">Dark mode</button></header><div class="layout"><aside><div class="eyebrow">Bundle identity</div><div class="card"><span class="pill" id="count"></span><p class="digest" id="digest"></p><p class="muted">Ordered sources. Original bytes. Reproducible output.</p></div><h2>Sources</h2><div class="sources" id="sources"></div></aside><main><div class="eyebrow">Local context reviewer</div><h1>A clear view of the assignment.</h1><p id="task"></p><nav aria-label="Review sections"><button data-tab="assembled" aria-selected="true">Assembled context</button><button data-tab="file">Selected file</button><button data-tab="assessment">Assessment</button><button data-tab="diff">Before / after</button></nav><section id="assembled"><h2>Complete assembled context</h2><p class="muted">Markdown instructions in recipe order. All original files, including assets, are available in Sources and materialized/.</p><div class="card"><pre id="context"></pre></div></section><section id="file" hidden><h2 id="file-title">Select a source</h2><div class="card"><p id="provenance" class="digest"></p><pre id="file-body"></pre></div></section><section id="assessment" hidden><h2>Assessment & improvement</h2><p id="method" class="muted"></p><div id="findings"></div><h3>Editable proposed recipe</h3><p class="muted">Exact duplicate top-level instruction files are omitted. Review task scope and every finding before adopting this proposal. Sources are never rewritten.</p><div class="card"><pre id="recipe"></pre></div></section><section id="diff" hidden><h2>Before / after</h2><p id="diff-note" class="muted"></p><div id="changes"></div></section><footer>Weave shows this explicit bundle, not ambient or hidden harness injection. Deterministic checks are review aids; they do not establish semantic correctness.</footer></main></div><script>
const data=/*PAYLOAD*/;
const b=data.bundle,$=id=>document.getElementById(id);
function text(id,value){$(id).textContent=value}
function node(tag,value,cls){const n=document.createElement(tag);if(value!==undefined)n.textContent=value;if(cls)n.className=cls;return n}
function tab(name){for(const id of ['assembled','file','assessment','diff'])$(id).hidden=id!==name;for(const button of document.querySelectorAll('[data-tab]'))button.setAttribute('aria-selected',String(button.dataset.tab===name))}
for(const button of document.querySelectorAll('[data-tab]'))button.onclick=()=>tab(button.dataset.tab);
function mode(dark){document.body.classList.toggle('dark',dark);text('theme',dark?'Light mode':'Dark mode');$('theme').setAttribute('aria-pressed',String(dark))}mode(matchMedia('(prefers-color-scheme: dark)').matches);$('theme').onclick=()=>mode(!document.body.classList.contains('dark'));
text('task',b.task);text('digest',b.digest);text('count',b.files.length+' files · '+b.files.reduce((n,f)=>n+f.bytes,0).toLocaleString()+' bytes');text('context',b.context);text('method',b.assessment.method);text('recipe',JSON.stringify(b.assessment.improved_recipe,null,2));
function decode(base64){return new TextDecoder().decode(Uint8Array.from(atob(base64),c=>c.charCodeAt(0)))}
function select(f){text('file-title',f.target);text('provenance',f.path+' → '+f.target+' · '+f.bytes+' bytes\nSHA-256 '+f.sha256);text('file-body',decode(f.data));tab('file')}
for(const [i,f] of b.files.entries()){const button=node('button',(i+1)+'. '+f.path);button.append(node('small',f.bytes+' bytes → '+f.target));button.onclick=()=>select(f);$('sources').append(button)}
if(!b.assessment.findings.length)$('findings').append(node('p','No lexical findings. This is not proof of correct or complete guidance.'));
for(const f of b.assessment.findings){const card=node('div',undefined,'card');card.append(node('span',f.rule,'pill'));const button=node('button',f.path+':'+f.line);button.onclick=()=>{const source=b.files.find(s=>s.path===f.path);if(source){select(source);const lines=decode(source.data).split('\n');text('file-body',lines.map((s,i)=>(i+1)+': '+s).join('\n'));$('file-title').scrollIntoView({block:'start'})}};card.append(node('p',f.detail),button);$('findings').append(card)}
text('diff-note',data.diff?data.diff.before_digest+' → '+data.diff.after_digest:'Create a comparison with hev context diff --before bundle-a --after bundle-b --out comparison, then open its index.html.');
if(data.diff){if(!data.diff.changes.length)$('changes').append(node('p','No changes.'));for(const c of data.diff.changes){const card=node('div',undefined,'card');card.append(node('h3',c.target+' · '+c.status));const grid=node('div',undefined,'diff-grid');for(const [label,value] of [['Before',c.before],['After',c.after]]){const col=node('div');col.append(node('h3',label),node('pre',value||'(absent)'));grid.append(col)}card.append(grid);$('changes').append(card)}}
</script></body></html>`
